SELECT document_id, user_id, permission, enabled, create_time, update_time FROM biz_document_user WHERE enabled = 1 AND permission IN ('READ', 'WRITE') AND document_id IN
#{documentId}
ORDER BY document_id ASC, user_id ASC

SELECT document_id, user_id, permission, enabled, create_time, update_time
FROM biz_document_user
WHERE document_id = #{documentId}
  AND user_id = #{userId}

SELECT document_id, user_id, permission, enabled, create_time, update_time
FROM biz_document_user
WHERE document_id = #{documentId}
  AND user_id = #{userId}
  AND enabled = 1

mapper.update:
UPDATE biz_document_user
SET enabled = 0,
    update_time = CURRENT_TIMESTAMP(3)
WHERE document_id = #{documentId}
  AND user_id = #{userId}
  AND EXISTS (
      SELECT 1
      FROM biz_document
      WHERE id = #{documentId}
        AND owner_user_id = #{ownerUserId}
        AND deleted = 0
  )
